using CsCom.CodeGeneration;

namespace CsCom.LibrarySets;

/// <summary>
/// The code generated for libraries generated together, see <see cref="LibrarySetGenerator"/>.
/// </summary>
public sealed class LibrarySetResult
{
    /// <summary>The generated files, in a folder per namespace, e.g. <c>Interop.Scripting/Dictionary.cs</c>.</summary>
    public required IReadOnlyList<GeneratedDocument> Documents { get; init; }

    /// <summary>The generated libraries: the references, then the libraries that are only used by them.</summary>
    public required IReadOnlyList<LibrarySetLibrary> Libraries { get; init; }

    /// <summary>The files that were read: the type libraries, the interop assemblies and the configuration files.</summary>
    public required IReadOnlyList<string> InputFiles { get; init; }
}

/// <summary>
/// A library generated by <see cref="LibrarySetGenerator"/>.
/// </summary>
/// <param name="Name">The name of the library.</param>
/// <param name="Guid">The library identifier.</param>
/// <param name="MajorVersion">The major version.</param>
/// <param name="MinorVersion">The minor version.</param>
/// <param name="Namespace">The namespace of its types.</param>
/// <param name="IsReferenced">
/// Whether the library is a reference, whose types are all generated; otherwise only the types used by the references are generated.
/// </param>
/// <param name="TypeCount">The number of generated types.</param>
public sealed record LibrarySetLibrary(string Name, Guid Guid, ushort MajorVersion, ushort MinorVersion, string Namespace, bool IsReferenced, int TypeCount);
